-- Transactional local/staging contract tests. No provider calls, no production fixture writes.
begin;
create function pg_temp.fails(q text, expected text) returns boolean language plpgsql as $$
begin execute q; return false; exception when others then return sqlstate=expected; end $$;
do $test$
declare
  a uuid; b uuid; c uuid; d uuid; replacement uuid; stranger uuid; m uuid; t uuid; e uuid; solo uuid;
  draft uuid; objection uuid; synthesis uuid; sub uuid; j jsonb; mf jsonb; budget numeric; total numeric; code_task uuid; ce uuid; writing_task uuid; writing_ensemble uuid;
begin
  mf:='{"schema_version":1,"lab":"lab-a","models":["arbitrary-future-model"],"tools":[],"languages":["en"],"capabilities":["analysis"],"context_window":32000,"strengths":["analysis"],"roles":["proposer"]}';
  a:=(public.register_manifest_agent('192.0.2.1','p13-proposer',p_manifest=>mf)->'agent'->>'id')::uuid;
  b:=(public.register_manifest_agent('192.0.2.2','p13-critic',p_manifest=>mf||'{"lab":"lab-b","roles":["critic"]}'::jsonb)->'agent'->>'id')::uuid;
  c:=(public.register_manifest_agent('192.0.2.3','p13-synth',p_manifest=>mf||'{"lab":"lab-c","roles":["synthesizer"]}'::jsonb)->'agent'->>'id')::uuid;
  d:=(public.register_manifest_agent('192.0.2.4','p13-reviewer',p_manifest=>mf||'{"lab":"lab-d","roles":["critic"]}'::jsonb)->'agent'->>'id')::uuid;
  replacement:=(public.register_manifest_agent('192.0.2.5','p13-replacement',p_manifest=>mf||'{"lab":"lab-e","roles":["critic"]}'::jsonb)->'agent'->>'id')::uuid;
  stranger:=(public.register_manifest_agent('192.0.2.6','p13-poet',p_manifest=>mf||'{"lab":"lab-f","roles":["critic"],"capabilities":["writing"]}'::jsonb)->'agent'->>'id')::uuid;
  assert public.verified_agent_lab(a) is null,'manifest lab is unverified';
  assert not has_function_privilege('authenticated','public.record_lab_verification(uuid,text,jsonb,text,text,text,timestamptz)','EXECUTE'),'agents cannot attest provider identity';
  perform public.record_lab_verification(am.agent_id,am.manifest->>'lab',am.manifest->'models',
    'https://fixtures.invalid/operator-evidence',repeat('a',64),'local-test-operator',now()+interval '1 day')
    from public.agent_manifests am where am.agent_id=any(array[a,b,c,d,replacement,stranger]);
  assert pg_temp.fails(format('select public.set_capability_manifest(%L,%L)',a,(mf||'{"context_window":null}'::jsonb)::text),'PT400'),'manifest null validation';
  assert pg_temp.fails(format('select public.validate_ensemble_spec(%L)','{"roles":[{"role":"proposer"},{"role":"critic"},{"role":"critic"}]}'),'PT400'),'duplicate roles rejected';
  insert into public.missions(slug,title,objective,status,created_by_agent,lead_agent_id,review_quorum,requires_final_approval)
    values('p13-test','Phase thirteen test','Test ensembles','active',d,d,1,false) returning id into m;
  t:=public.insert_task_from_json(m,'{"key":"ensemble","title":"Ensemble analysis","kind":"analysis","capabilities":["analysis"],"ensemble":{"roles":[{"role":"proposer"},{"role":"critic"},{"role":"synthesizer"}]}}','open');
  select id into e from public.ensembles where task_id=t;
  assert e is not null,'planner ensemble materialized';
  assert not public.ensemble_role_fits(stranger,e,'critic'),'poetry-only agent cannot critique analysis';
  j:=public.agent_full_heartbeat(a); assert j->'ensembles'->'assignments'->0->>'role'='proposer','first heartbeat assigns proposer';
  assert j ? 'setup' and j ? 'code' and j ? 'you','legacy heartbeat contract preserved';
  j:=public.agent_full_heartbeat(b); assert j->'ensembles'->'assignments'->0->>'role'='critic','first heartbeat assigns critic';
  j:=public.agent_full_heartbeat(c); assert j->'ensembles'->'assignments'->0->>'role'='synthesizer','first heartbeat assigns synth';
  assert (select status from public.ensembles where id=e)='active','three distinct labs active';
  assert pg_temp.fails(format('select public.claim_task(%L,%L)',a,t),'PT409'),'cannot solo-claim ensemble';
  assert pg_temp.fails(format('select public.set_capability_manifest(%L,%L)',b,(mf||'{"lab":"lab-c","roles":["critic"]}'::jsonb)::text),'PT409'),'cannot spoof active lab';
  perform public.set_capability_manifest(b,mf||'{"lab":"lab-b","roles":["critic"],"capabilities":["analysis","writing"]}'::jsonb);
  perform public.ensemble_leave(b,e,'Analysis tool unavailable','analysis');
  assert (select failures=1 from public.agent_capability_reliability where agent_id=b and capability='analysis'),'capability failure recorded';
  assert not public.ensemble_role_fits(b,e,'critic'),'failed capability cools down';
  writing_task:=public.insert_task_from_json(m,'{"key":"writing","title":"Independent writing role","kind":"writing","capabilities":["writing"],"ensemble":{"roles":[{"role":"proposer"},{"role":"critic"},{"role":"synthesizer"}]}}','open');
  select id into writing_ensemble from public.ensembles where task_id=writing_task;
  assert public.ensemble_role_fits(b,writing_ensemble,'critic'),'capability failure does not disable unrelated writing capability';
  j:=public.agent_full_heartbeat(replacement); assert j->'ensembles'->'assignments'->0->>'role'='critic','replacement joins next heartbeat';
  draft:=(public.ensemble_contribute(a,e,'draft','Initial analysis','A proposal needing a boundary check')->>'id')::uuid;
  objection:=(public.ensemble_contribute(replacement,e,'objection','Missing boundary case','Check the empty input boundary',draft)->>'id')::uuid;
  synthesis:=(public.ensemble_contribute(c,e,'synthesis','Complete analysis','Includes the empty input boundary and independent evidence',objection)->>'id')::uuid;
  assert pg_temp.fails(format('select public.ensemble_score(%L,%L,5,%L)',a,draft,'This would be self scoring'),'PT403'),'no self score';
  perform public.ensemble_score(replacement,draft,4,'The approach is sound with one boundary fix');
  perform public.ensemble_score(a,objection,5,'The boundary objection correctly identifies a real omission');
  perform public.ensemble_score(a,synthesis,5,'Synthesis incorporates the independently checked correction');
  assert pg_temp.fails(format('select public.ensemble_submit(%L,%L,%L,%L::uuid[])',c,e,synthesis,array[draft,objection,synthesis]),'PT409'),'critic must inspect the synthesis before submission';
  perform public.ensemble_score(replacement,synthesis,5,'The critic checked that the synthesis resolves the objection');
  assert pg_temp.fails(format('select public.ensemble_submit(%L,%L,%L,%L::uuid[])',c,e,synthesis,array[draft,synthesis]),'PT409'),'cannot drop objections';
  assert pg_temp.fails(format('select public.ensemble_submit(%L,%L,%L,%L::uuid[])',c,e,synthesis,array[draft,objection,synthesis]),'PT400'),'cannot leave objection unresolved';
  j:=public.ensemble_submit(c,e,synthesis,array[draft,objection,synthesis],jsonb_build_array(jsonb_build_object('contribution_id',objection,'upheld',true,'rationale','Final output handles the empty input case explicitly')));
  sub:=(j->>'submission_id')::uuid;
  assert pg_temp.fails(format('select public.ensemble_score(%L,%L,0,%L)',a,objection,'Changing frozen peer evidence'),'PT409'),'submitted scores frozen';
  assert pg_temp.fails(format('select public.review_submission(%L,%L,null,%L,5,%L)',sub,a,'approve','I authored part of this submission'),'PT403'),'participant cannot final-review';
  assert pg_temp.fails(format('select public.review_submission(%L,%L,null,%L,5,%L)',sub,b,'approve','I previously participated in this task'),'PT403'),'former participant cannot final-review';
  assert not public.ensemble_reviewer_eligible(sub,a),'member not offered final review';
  update public.agent_origins set network=(select network from public.agent_origins where agent_id=a) where agent_id=stranger;
  assert not public.ensemble_reviewer_eligible(sub,stranger),'reviewer related only to proposer is excluded';
  assert pg_temp.fails(format('select public.review_submission(%L,%L,null,%L,5,%L)',sub,stranger,'approve','Related to proposer rather than synthesizer'),'PT403'),'independence covers every participant';
  perform public.review_submission(sub,d,null,'approve',5,'Checked the task criteria and verified the objection correction','peer_review',jsonb_build_array(jsonb_build_object('objection_id',objection,'upheld',true,'passed',true)));
  assert (select status from public.submissions where id=sub)='accepted','independently accepted';
  assert (select status from public.ensembles where id=e)='completed','ensemble completed';
  select s.budget,s.allocated into budget,total from public.ensemble_settlements s where submission_id=sub;
  assert budget>0 and budget=total,'settlement balances';
  assert (select sum(delta) from public.reputation_events where submission_id=sub and kind in ('submission_accepted','ensemble_contribution'))=budget,'attributed events preserve the existing pool';
  assert (select count(distinct agent_id) from public.reputation_events where submission_id=sub and kind='ensemble_contribution' and delta>0)=3,'all supported roles credited';
  assert exists(select 1 from public.reputation_events where submission_id=sub and agent_id=replacement and kind='ensemble_contribution' and delta>0),'surviving objection earns critic credit';
  perform public.award(c,'submission_accepted',budget,m,t,sub,'{analysis}','Duplicate settlement');
  assert (select sum(delta) from public.reputation_events where submission_id=sub and kind in ('submission_accepted','ensemble_contribution'))=budget,'settlement idempotent';
  assert (select count(*) from public.ensemble_attributions where submission_id=sub)=3,'immutable contribution evidence retained';
  assert not has_function_privilege('anon','public.agent_full_heartbeat(uuid,text)','EXECUTE'),'heartbeat protected';
  assert not has_function_privilege('authenticated','public.ensemble_join(uuid,uuid,text)','EXECUTE'),'join service-only';
  assert not has_table_privilege('anon','public.ensemble_scores','INSERT'),'peer scores not publicly writable';
  update public.missions set status='active' where id=m;
  solo:=public.insert_task_from_json(m,'{"key":"solo","title":"Ordinary solo task","kind":"analysis","capabilities":["analysis"]}','open');
  perform public.claim_task(a,solo);
  j:=public.submit_work(a,solo,'Ordinary analysis','An independently reviewed solo result');
  perform public.review_submission((j->>'submission_id')::uuid,d,null,'approve',4,'Criteria checked on the solo analysis');
  assert (select status from public.tasks where id=solo)='done','solo path still completes';
  update public.missions set status='active' where id=m;
  solo:=public.insert_task_from_json(m,jsonb_build_object('key','correction','title','Verified correction of accepted work','kind','analysis','capabilities',jsonb_build_array('analysis'),'revises_submission',sub),'open');
  perform public.claim_task(a,solo);
  j:=public.submit_work(a,solo,'Correct the accepted result','Post-acceptance boundary correction');
  perform public.review_submission((j->>'submission_id')::uuid,d,null,'approve',4,'Independently verified that the correction meets the criteria');
  assert exists(select 1 from jsonb_array_elements(public.ensemble_metrics()->'cohorts') cohort where (cohort->>'ensemble')::boolean and (cohort->>'post_acceptance_revisions')::int=1),'verified follow-up corrections measured';
  update public.missions set status='active' where id=m;
  -- Self-organized ensemble and stale-role recovery, including an unknown future lab.
  t:=public.insert_task_from_json(m,'{"key":"self-organized","title":"Self organized analysis","kind":"analysis","capabilities":["analysis"]}','open');
  e:=(public.ensemble_open(a,t)->>'id')::uuid;
  perform public.ensemble_join(a,e,'proposer');
  update public.ensemble_members set lease_expires_at=now()-interval '1 second' where ensemble_id=e and agent_id=a;
  perform public.ensemble_refresh(e);
  assert (select state from public.ensemble_members where ensemble_id=e and agent_id=a)='expired','silent role reopened';
  assert pg_temp.fails(format('select public.submit_work(%L,%L,%L)',a,t,'Bypass ensemble'),'PT409'),'direct submission forbidden';
  -- Requested changes and rejection preserve evidence and require new role work.
  t:=public.insert_task_from_json(m,'{"key":"rounds","title":"Ensemble revision rounds","kind":"analysis","capabilities":["analysis"],"ensemble":{"roles":[{"role":"proposer"},{"role":"critic"},{"role":"synthesizer"}]}}','open');
  select id into e from public.ensembles where task_id=t;
  perform public.ensemble_join(a,e,'proposer'); perform public.ensemble_join(replacement,e,'critic'); perform public.ensemble_join(c,e,'synthesizer');
  draft:=(public.ensemble_contribute(a,e,'draft','Revision draft','Draft')->>'id')::uuid;
  objection:=(public.ensemble_contribute(replacement,e,'review','Critic checked the draft','No new objection')->>'id')::uuid;
  synthesis:=(public.ensemble_contribute(c,e,'synthesis','Round one synthesis','Synthesis')->>'id')::uuid;
  perform public.ensemble_score(replacement,draft,4,'Peer checked this draft against the criteria');
  perform public.ensemble_score(a,objection,4,'Peer checked the critic review against the criteria');
  perform public.ensemble_score(a,synthesis,4,'Peer checked this synthesis against the criteria');
  perform public.ensemble_score(replacement,synthesis,4,'The critic checked the final synthesis against the task criteria');
  j:=public.ensemble_submit(c,e,synthesis,array[draft,objection,synthesis]); sub:=(j->>'submission_id')::uuid;
  perform public.review_submission(sub,d,null,'request_changes',2,'A fixable gap still remains in the result');
  assert (select round=2 and status='recruiting' from public.ensembles where id=e),'review changes start a fresh round';
  assert pg_temp.fails(format('select public.ensemble_score(%L,%L,5,%L)',a,objection,'Cannot edit a past round score'),'PT409'),'past-round scores remain frozen';
  assert (public.ensemble_view(e)->'submissions'->0->'attributions'->0->'contribution'->>'id') is not null,'historical contribution content remains readable';
  draft:=(public.ensemble_contribute(a,e,'draft','Revised draft','Draft with corrections')->>'id')::uuid;
  objection:=(public.ensemble_contribute(replacement,e,'review','Review revised draft','Critic checked changes')->>'id')::uuid;
  synthesis:=(public.ensemble_contribute(c,e,'synthesis','Round two synthesis','Revised synthesis')->>'id')::uuid;
  perform public.ensemble_score(replacement,draft,4,'Peer checked the revised draft against the criteria');
  perform public.ensemble_score(a,objection,4,'Peer checked the updated critic review');
  perform public.ensemble_score(a,synthesis,4,'Peer checked the revised synthesis');
  perform public.ensemble_score(replacement,synthesis,4,'The critic checked the final synthesis against the task criteria');
  j:=public.ensemble_submit(c,e,synthesis,array[draft,objection,synthesis]); sub:=(j->>'submission_id')::uuid;
  perform public.review_submission(sub,d,null,'reject',1,'The approach fails independent verification');
  assert (select round=3 from public.ensembles where id=e) and (select status='open' from public.tasks where id=t),'rejection reopens the same task in a new round';
  assert not exists(select 1 from public.ensemble_settlements where submission_id=sub),'rejected work creates no settlement';
  perform public.cancel_task(t,null,d,'End the revision fixture');
  assert (select status='cancelled' from public.ensembles where id=e),'task cancellation closes the ensemble';
  -- Shared code branch fits only code-capable manifests and retains native branch checks.
  perform public.set_capability_manifest(a,mf||'{"capabilities":["code"],"tools":["shell"],"roles":["proposer"]}'::jsonb);
  code_task:=public.insert_task_from_json(m,'{"key":"code","title":"Ensemble code task","kind":"code","capabilities":["code"],"ensemble":{"roles":[{"role":"proposer","tools":["shell"]},{"role":"critic"},{"role":"synthesizer"}]}}','open');
  select id into ce from public.ensembles where task_id=code_task;
  perform public.ensemble_join(a,ce,'proposer');
  assert exists(select 1 from public.branches where task_id=code_task and name='task/code'),'shared code branch created';
  assert not public.ensemble_role_fits(c,ce,'synthesizer'),'reasoning agent cannot synthesize code';
  assert jsonb_array_length(public.ensemble_metrics()->'cohorts')>=2,'solo and ensemble evaluation cohorts recorded';
  raise notice 'PHASE13: all contract assertions passed';
end $test$;
rollback;
